import type { BoxProps } from "../Box/Box.js";
import type { StyleHandlers } from "../hooks/useStyleProps.js";
import type { AdaptiveProp, BoxAlignmentStyleProps, LayoutComponentProps } from "../types.js";
import "./Flex.css";
type AlignPropsNotSupportedByFlex = 'justifyItems' | 'placeItems';
export interface FlexStyleProps extends Omit<BoxAlignmentStyleProps, AlignPropsNotSupportedByFlex> {
    /** The direction in which to layout children. */
    direction?: AdaptiveProp<React.CSSProperties['flexDirection']>;
    /** Whether to wrap items onto multiple lines. */
    wrap?: AdaptiveProp<boolean | React.CSSProperties['flexWrap']>;
}
export interface FlexProps<T extends React.ElementType = 'div'> extends BoxProps<T>, FlexStyleProps {
    /**
     * display: inline-flex;
     */
    inline?: boolean;
}
export declare const flexStyleHandlers: StyleHandlers<keyof FlexStyleProps>;
/**
 * Flexbox model utility component.
 *
 * ```tsx
 * import {Flex, Button} from '@gravity-ui/uikit';
 *
 * <Flex gap="spacing-2">
 *  <Button>
 *      Button 1
 *  </Button>
 *  <Button>
 *      Button 2
 *  </Button>
 * </Flex>
 * ```
 *
 * Use build in media goods via props
 *
 * ```tsx
 * <Flex
 *  // gap dynamically changes based on the current media query
 *  gap={{s: 'spacing-1', m: 'spacing-5'}}
 *  // `flex-direction: row` will be applied to `m`, 'l', 'xl', '2xl' and `3xl`
 *  direction={{s: 'column', m: 'row'}}
 * >
 *  {...}
 * </Flex>
 * ```
 * ---
 * Storybook - https://preview.gravity-ui.com/uikit/?path=/docs/layout--playground#flex
 */
export declare const Flex: (<C extends React.ElementType = "div">(props: LayoutComponentProps<C, FlexProps<C>>) => React.ReactElement) & {
    displayName: string;
};
export {};

