import {join, extname} from 'node:path';
const root = '/tmp/pwcheck/site';
const types = {'.html':'text/html','.js':'text/javascript','.css':'text/css'};
export const server = http.createServer(async (q, s) => {
  const p = q.url === '/' ? '/index.html' : q.url.split('?')[0];
  try { s.setHeader('content-type', types[extname(p)] || 'application/octet-stream'); s.end(await readFile(join(root, p))); }
