import {chromium} from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 800}});
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));

await page.goto('http://localhost:5173/', {waitUntil: 'networkidle'});
await page.screenshot({path: '/tmp/pwcheck/login-light.png', fullPage: true});

const report = {};
report.h1 = await page.locator('h1').innerText();
report.labels = await page.locator('label').allInnerTexts();
report.emailType = await page.locator('#login-email').getAttribute('type');
report.emailRequired = await page.locator('#login-email').evaluate((el) => el.required);
report.passwordType = await page.locator('#login-password').getAttribute('type');
report.passwordRequired = await page.locator('#login-password').evaluate((el) => el.required);
report.buttonText = await page.locator('button[type="submit"]').innerText();
report.checkboxLabel = await page.locator('label:has-text("Запомнить меня")').innerText();
report.hasCopyButton = await page.locator('.g-text-input button[aria-label*="опир"], .g-text-input button[aria-label*="Copy"]').count();

// Label association: clicking the label focuses the input
await page.locator('label[for="login-email"]').click();
report.emailFocusedAfterLabelClick = await page.evaluate(() => document.activeElement?.id);

// Checkbox toggle
const cb = page.locator('label:has-text("Запомнить меня") input[type="checkbox"]');
report.checkboxInitial = await cb.isChecked();
await page.getByText('Запомнить меня').click();
report.checkboxAfterClick = await cb.isChecked();

// Native required validation: empty submit must not submit
let submitted = false;
page.on('request', (r) => { if (r.method() === 'POST') submitted = true; });
await page.locator('button[type="submit"]').click();
report.emailValidity = await page.locator('#login-email').evaluate((el) => el.validationMessage);

// Typing works
await page.locator('#login-email').fill('user@example.com');
await page.locator('#login-password').fill('secret');
report.emailValue = await page.locator('#login-email').inputValue();
report.passwordValue = await page.locator('#login-password').inputValue();

// Mobile viewport screenshot
await page.setViewportSize({width: 375, height: 700});
await page.screenshot({path: '/tmp/pwcheck/login-mobile.png', fullPage: true});

// Dark theme screenshot
await page.emulateMedia({colorScheme: 'dark'});
await page.setViewportSize({width: 1280, height: 800});
await page.screenshot({path: '/tmp/pwcheck/login-dark.png', fullPage: true});

report.errors = errors;
console.log(JSON.stringify(report, null, 2));
await browser.close();
EOF
